<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { channelName, announceCommissionChange } from '$lib/commission-sync';
  import { enhance } from '$app/forms';
  import { goto, invalidateAll, beforeNavigate, afterNavigate } from '$app/navigation';
  import { page } from '$app/stores';
  import Icon from '$lib/components/Icon.svelte';
  import type { PageData, ActionData } from './$types';
  export let data: PageData;
  export let form: ActionData;
  const statuses = { new: 'Pendentes',review:'Em análise', in_progress: 'Em produção', converted: 'Aprovadas', completed: 'Concluídas', archived: 'Arquivadas' };
  const priorities = { urgent: 'Urgente / 24 FPS', normal: 'Normal', planning: 'Planejamento' };
  type Scene = PageData['inquiries'][number];
  let root: HTMLElement, drawer: HTMLDialogElement, createDialog: HTMLDialogElement;
  let selectedId = '', newOpen = false, enhanced = false, busy = false, copied = '';
  let toast='';
  let liveMetrics:PageData['metrics']|null=null, liveVersion='', syncing=false, pendingRefresh=false;
  let syncDisposed=false,syncController:AbortController|null=null;
  $: if(data.metrics){liveMetrics=data.metrics;}
  async function sync(){
    if(syncDisposed||syncing||document.hidden||!navigator.onLine)return;syncing=true;syncController=new AbortController();
    try{const response=await fetch('/api/commissions',{headers:liveVersion?{'If-None-Match':liveVersion}:{},signal:AbortSignal.any([syncController.signal,AbortSignal.timeout(8000)])});if(syncDisposed)return;if(response.status===304){if(pendingRefresh&&!busy&&!selectedId&&!newOpen){pendingRefresh=false;await invalidateAll();}return;}if(response.status===401){window.location.replace('/admin/entrar');return;}if(!response.ok)return;const snapshot=await response.json();if(syncDisposed)return;liveMetrics=snapshot.metrics;const changed=liveVersion&&liveVersion!==snapshot.version;liveVersion=snapshot.version;if(changed)pendingRefresh=true;if(pendingRefresh&&!busy&&!selectedId&&!newOpen){pendingRefresh=false;await invalidateAll();}}catch{}finally{syncing=false;}
  }
  let query = data.search, searchTimer: ReturnType<typeof setTimeout>;
  let trigger: HTMLElement | null = null;
  let flip: typeof import('gsap/Flip').Flip | null = null, state: ReturnType<typeof import('gsap/Flip').Flip.getState> | null = null;
  $: scenes = data.inquiries;
  $: selected = scenes.find(scene => scene.id === selectedId);
  $: metrics = liveMetrics||data.metrics;  $: serviceOptions = [...new Set([...data.services, ...data.settings.servicesText.split('\n').map(s=>s.trim()).filter(Boolean)])];
  function date(value:string) { return new Date(value).toLocaleString('pt-BR', {timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}); }
  async function openScene(scene:Scene, event:MouseEvent) { trigger=event.currentTarget as HTMLElement; selectedId=scene.id; await tick(); drawer.showModal(); }
  function closeScene() { drawer?.close(); selectedId=''; trigger?.focus(); }
  async function newScene(event:MouseEvent) { trigger=event.currentTarget as HTMLElement; newOpen=true; await tick(); createDialog.showModal(); }
  function closeCreate() { createDialog?.close(); newOpen=false; trigger?.focus(); }
  async function copyEmail(value:string) { try { await navigator.clipboard.writeText(value); copied=value;toast='E-mail copiado para a área de transferência.'; } catch { toast='Não foi possível copiar. Selecione o endereço na ficha.'; } }
  async function copyBrief(scene:Scene){try{await navigator.clipboard.writeText(scene.name+'\n'+scene.email+'\n'+scene.service+'\n\n'+scene.brief);toast='Briefing copiado para a área de transferência.';}catch{toast='Não foi possível copiar. Selecione o texto da ficha.';}}
  const replyTo=(scene:Scene)=>'mailto:'+encodeURIComponent(scene.email)+'?subject='+encodeURIComponent('[IKARI STUDIO] Orçamento & Direção — Take #'+scene.id.toUpperCase())+'&body='+encodeURIComponent('Olá, '+scene.name+'!\n\nSobre sua ideia:\n'+scene.brief+'\n\n');
  const money=(cents:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100);
  function filters(status = data.status, service = data.service,priority:string=data.priority) {
    const params = new URLSearchParams(); if(status)params.set('estado',status); if(service)params.set('servico',service); if(priority)params.set('prioridade',priority); if(query.trim())params.set('busca',query.trim().slice(0,120));
    void goto('/admin/pedidos?'+params.toString(),{keepFocus:true,noScroll:true,replaceState:true});
  }
  function search() { clearTimeout(searchTimer); searchTimer=setTimeout(()=>filters(),350); }
  const submit:import('@sveltejs/kit').SubmitFunction = ({formData,action,cancel}) => {
    const operation=['create','save','status','delete'].find(name=>action.searchParams.has('/'+name));
    busy=true;
    if(operation){
      cancel();
      void (async()=>{try{
        const response=await fetch('/api/commissions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:operation,...Object.fromEntries(formData)})});
        const result=await response.json();if(!response.ok||result.success===false)throw new Error(result.error||'Não foi possível salvar.');
        toast=typeof result.success==='string'?result.success:'Cena salva na mesa.';closeScene();closeCreate();announceCommissionChange();liveVersion='';await invalidateAll();await sync();
      }catch(error){toast=error instanceof Error?error.message:'Não foi possível salvar. Seus campos continuam aqui.';}finally{busy=false;}})();
      return;
    }
    return async ({update,result})=>{try{await update();if(result.type==='success'){announceCommissionChange();closeScene();closeCreate();}}finally{busy=false;}};
  };
  beforeNavigate(()=>{if(flip&&root&&!matchMedia('(prefers-reduced-motion: reduce)').matches)state=flip.getState(root.querySelectorAll('.scene-card'));});
  afterNavigate(()=>{query=data.search;if(flip&&state){flip.from(state,{duration:.38,ease:'power3.out',absolute:true});state=null;}});
  onMount(()=>{
    enhanced=true;syncDisposed=false; let stopped=false,context:{revert:()=>void}|undefined;
    Promise.all([import('gsap'),import('gsap/Flip')]).then(([{gsap},{Flip}])=>{
      if(stopped)return; gsap.registerPlugin(Flip); flip=Flip;
      if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
      context=gsap.context(()=>{gsap.from('.board-title',{y:26,opacity:0,duration:.65,ease:'power3.out'});gsap.from('.studio-metric',{y:14,opacity:0,duration:.45,stagger:.07,ease:'power3.out'});gsap.from('.scene-card',{y:20,opacity:0,rotation:-1,duration:.5,stagger:.05,ease:'power3.out'});},root);
    }).catch(()=>{});
    const poll=setInterval(()=>void sync(),3000);const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel(channelName):null;if(channel)channel.onmessage=()=>void sync();const wake=()=>void sync();document.addEventListener('visibilitychange',wake);window.addEventListener('online',wake);void sync();
    return()=>{stopped=true;syncDisposed=true;syncController?.abort();context?.revert();clearInterval(poll);channel?.close();document.removeEventListener('visibilitychange',wake);window.removeEventListener('online',wake);clearTimeout(searchTimer);};
  });
</script>

<svelte:head><title>Mesa de comissões — {data.settings.brandName}</title></svelte:head>
<section class="studio-board" bind:this={root}>
  <span class="board-kanji" aria-hidden="true">制作</span>
  <header class="board-heading">
    <div><p class="studio-kicker"><span class="record-dot"></span> IKARI STUDIO OS / MESA DE DIREÇÃO</p><h1 class="board-title">Cada ideia.<br/><span>Uma nova cena.</span></h1><p class="board-intro">Do primeiro roteiro ao último corte. Seus pedidos, referências e notas de direção no mesmo quadro.</p></div>
    <div class="board-actions"><button class="studio-button lime" onclick={newScene}><Icon name="plus" size={18}/>Nova comissão</button><form method="POST" action="/admin/pedidos/exportar" data-sveltekit-reload><button class="studio-button" type="submit" name="format" value="csv"><Icon name="download" size={17}/>Exportar CSV</button><button class="studio-button" type="submit" name="format" value="json">Backup JSON</button></form><button class="studio-refresh" onclick={()=>invalidateAll()}><Icon name="refresh" size={16}/>Atualizar mesa</button></div>
  </header>
  {#if form?.error}<p class="studio-notice error" role="alert">{form.error}</p>{:else if form?.success}<p class="studio-notice" role="status">{form.success}</p>{/if}
  {#if toast}<p class="studio-notice" role="status">{toast}<button type="button" class="studio-refresh" onclick={()=>toast=''}>Fechar aviso</button></p>{/if}

  <div class="studio-metrics">
    <article class="studio-metric" style="--metric:#FF6B4A"><span>01 / NOVOS ROTEIROS</span><strong>{metrics.new.toString().padStart(2,'0')}</strong><p>Pendentes</p></article>
    <article class="studio-metric" style="--metric:#B8FF01"><span>02 / STORYBOARD</span><strong>{metrics.in_progress.toString().padStart(2,'0')}</strong><p>Em produção</p></article>
    <article class="studio-metric" style="--metric:#00E5F5"><span>03 / ÚLTIMO CORTE</span><strong>{metrics.completed.toString().padStart(2,'0')}</strong><p>Concluídas</p></article>
    <article class="studio-metric" style="--metric:#F3EFE6"><span>04 / NO ARQUIVO</span><strong>{metrics.total.toString().padStart(2,'0')}</strong><p>{metrics.converted} aprovadas · {metrics.archived} arquivadas</p></article>
  </div>
  <p class="studio-revenue">ORÇAMENTOS DE CENAS CONCLUÍDAS <strong>{money(metrics.revenueCents)}</strong><span>Soma dos valores registrados nas fichas concluídas; não comprova recebimento financeiro.</span></p>

    <form method="GET" class="studio-filters" onsubmit={event=>{event.preventDefault();filters();}}>
      <label class="studio-search"><span>Buscar no arquivo</span><input type="search" name="busca" bind:value={query} maxlength="120" placeholder="Nome, e-mail ou briefing" oninput={search}/></label>
      <label><span>Tipo de serviço</span><select name="servico" value={data.service} onchange={event=>filters(data.status,event.currentTarget.value)}><option value="">Todos os serviços</option>{#each data.services as service}<option value={service}>{service}</option>{/each}</select></label>
      <label><span>Prioridade</span><select name="prioridade" value={data.priority} onchange={event=>filters(data.status,data.service,event.currentTarget.value)}><option value="">Todas as prioridades</option>{#each Object.entries(priorities) as [value,label]}<option {value}>{label}</option>{/each}</select></label>
      <input type="hidden" name="estado" value={data.status}/><button class="studio-button" type="submit">Buscar<Icon name="arrow" size={16}/></button>
    </form>
    <nav class="studio-statuses" aria-label="Estado das comissões"><a href="/admin/pedidos" class:active={!data.status} onclick={event=>{event.preventDefault();filters('');}}>Todas <b>{metrics.total}</b></a>{#each Object.entries(statuses) as [value,label]}<a href={'?estado='+value} class:active={data.status===value} onclick={event=>{event.preventDefault();filters(value);}}>{label} <b>{metrics[value as keyof typeof statuses]}</b></a>{/each}</nav>
  {#if data.limited}<p class="studio-notice">Busca privada na janela {data.window+1} do arquivo (até 1.000 fichas por janela). Use os controles abaixo para consultar as próximas fichas. As métricas contam todo o arquivo.</p>{/if}
  <div class="scene-grid" aria-label="Comissões recebidas" aria-live="polite">
    <svg class="board-thread" viewBox="0 0 1000 700" preserveAspectRatio="none" aria-hidden="true"><path d="M50 20 Q320 150 180 340 T570 570 Q800 490 960 650" fill="none" stroke="#E62E2D" stroke-width="2"/></svg>
    {#each scenes as scene,index (scene.id)}
      <article class="scene-card" data-flip-id={scene.id} style={'--card-angle:'+([-1.1,.9,-.6][index%3])+'deg;--scene-color:'+(scene.status==='new'?'#FF6B4A':scene.status==='completed'?'#00E5F5':'#B8FF01')}>
        <div class="scene-card-top"><span class="scene-pin" aria-hidden="true"></span><span>TAKE #{String((data.page-1)*data.pageSize+index+1).padStart(2,'0')}</span><span class="scene-status">{statuses[scene.status]}</span></div>
        {#if scene.reference}<div class="scene-reference"><img src={scene.reference.coverUrl} alt={scene.reference.coverAlt||scene.reference.title} width="96" height="96"/><span>FRAME DE REFERÊNCIA<strong>{scene.reference.title}</strong></span></div>{:else}<div class="scene-reference no-reference"><span aria-hidden="true">+</span><p>Uma cena<br/>ainda por criar.</p></div>{/if}
        <div class="scene-copy"><h2>{scene.name}</h2><a class="scene-email" href={'mailto:'+scene.email}>{scene.email}</a><p class="scene-service">{scene.service}</p><p class="scene-excerpt">{scene.brief}</p><div class="scene-meta"><span>{priorities[scene.priority||'normal']}</span><time datetime={scene.createdAt}>{date(scene.createdAt)}</time></div></div>
        {#if enhanced}<button class="scene-open" onclick={event=>openScene(scene,event)}>Abrir ficha de direção<Icon name="diagonal" size={18}/></button>{:else}<details class="scene-fallback"><summary>Abrir ficha e editar</summary><p>{scene.brief}</p><form method="POST" action="?/save"><input type="hidden" name="id" value={scene.id}/><input type="hidden" name="quoteCents" value={scene.quoteCents||0}/><input type="hidden" name="dueDate" value={scene.dueDate||''}/>{#each ['rough','cleanup','edit','render'] as stage}{#if scene.checklist?.[stage as 'rough'|'cleanup'|'edit'|'render']}<input type="hidden" name={stage} value="on"/>{/if}{/each}<label>Estado<select name="status" value={scene.status}>{#each Object.entries(statuses) as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>Prioridade<select name="priority" value={scene.priority||'normal'}>{#each Object.entries(priorities) as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>Notas internas<textarea name="notes" maxlength="4000">{scene.notes||''}</textarea></label><button class="studio-button lime">Salvar ficha</button></form></details>{/if}
      </article>
    {:else}<div class="studio-empty"><span aria-hidden="true">01</span><h2>O próximo roteiro<br/>começa aqui.</h2><p>{data.search||data.status||data.service?'Nenhuma ficha corresponde a este recorte. Altere os filtros para explorar o restante do arquivo.':'As ideias enviadas pelo formulário de Contato chegam a esta mesa. A atualização acontece a cada 30 segundos enquanto ela está aberta.'}</p><a class="studio-button" href="/admin/pedidos">Limpar filtros</a></div>{/each}
  </div>
  {#if (data.hasNextWindow || data.window>0)}<nav class="studio-pages" aria-label="Janelas de busca no arquivo cifrado">{#if data.window>0}<a href={'?'+new URLSearchParams({estado:data.status,busca:data.search,servico:data.service,prioridade:data.priority,janela:String(data.window-1)})}>Buscar nas 1.000 fichas anteriores</a>{/if}{#if data.hasNextWindow}<a href={'?'+new URLSearchParams({estado:data.status,busca:data.search,servico:data.service,prioridade:data.priority,janela:String(data.window+1)})}>Buscar nas próximas 1.000 fichas<Icon name="arrow" size={16}/></a>{/if}</nav>{/if}
  <footer class="board-bottom"><span>NOTAS INTERNAS / ACESSO RESERVADO À DIREÇÃO</span><p>Alterações de estado não enviam mensagens ao cliente. “Aprovada” e “Concluída” são etapas distintas.</p></footer>
  <nav class="studio-pages" aria-label="Páginas de comissões">{#if data.page>1}<a href={'?'+new URLSearchParams({pagina:String(data.page-1),estado:data.status,busca:data.search,servico:data.service,prioridade:data.priority,janela:String(data.window)})}>Mais recentes<Icon name="arrow" size={17}/></a>{/if}<span>Página {data.page} / {Math.max(1,Math.ceil(data.total/data.pageSize))} · {data.total} fichas neste recorte</span>{#if data.page*data.pageSize<data.total}<a href={'?'+new URLSearchParams({pagina:String(data.page+1),estado:data.status,busca:data.search,servico:data.service,prioridade:data.priority,janela:String(data.window)})}>Mais antigas<Icon name="arrow" size={17}/></a>{/if}</nav>
  <details class="studio-import"><summary>Restaurar fichas de um backup JSON</summary><p>Arquivo privado deste estúdio, até 500 fichas / 20 MB. IDs existentes são preservados e nunca sobrescritos. Primeiro valide a prévia; só confirme depois de conferir o resultado.</p><form method="POST" action="?/import" enctype="multipart/form-data" use:enhance={submit}><label>Arquivo JSON<input type="file" name="backup" accept="application/json,.json" required/></label><div><button class="studio-button" name="confirm" value="no">Validar prévia</button><button class="studio-button lime" name="confirm" value="yes">Importar sem sobrescrever</button></div></form></details>
</section>

{#if selected}
<dialog class="director-drawer" bind:this={drawer} onclose={()=>{selectedId='';trigger?.focus();}} aria-labelledby="director-heading">
  <div class="drawer-heading"><p class="studio-kicker">CREDENCIAL DE DIREÇÃO / FICHA DE CENA</p><button class="drawer-close" onclick={closeScene} aria-label="Fechar ficha"><Icon name="close" size={24}/></button></div>
  <h2 id="director-heading">{selected.name}</h2><span class="drawer-status">{statuses[selected.status]} / {selected.service}</span>
  <div class="drawer-contact"><a href={replyTo(selected)}>Responder por e-mail<Icon name="diagonal" size={16}/></a><button type="button" onclick={()=>copyEmail(selected!.email)}><Icon name="copy" size={16}/>{copied===selected.email?'Copiado':'Copiar e-mail'}</button><button type="button" onclick={()=>copyBrief(selected!)}>Copiar briefing</button></div>
  {#if toast}<p class="studio-notice" role="status">{toast}</p>{/if}
  <time datetime={selected.createdAt}>Recebida em {date(selected.createdAt)}</time>
  {#if selected.reference}<div class="drawer-reference"><img src={selected.reference.coverUrl} alt={selected.reference.coverAlt||selected.reference.title} width="100" height="100"/><span>PROJETO DE REFERÊNCIA<strong>{selected.reference.title}</strong></span></div>{/if}
  <div class="drawer-brief"><span class="studio-kicker">ROTEIRO / PEDIDO ORIGINAL</span><p>{selected.brief}</p></div>

    {#if form?.error}<p class="studio-notice error" role="alert">{form.error}</p>{/if}
    <form method="POST" action="?/save" use:enhance={submit} class="director-form">
      <label>Nome do cliente<input name="name" required minlength="2" maxlength="120" value={selected.name}/></label><label>E-mail<input name="email" type="email" required maxlength="254" value={selected.email}/></label><label>Tipo de serviço<input name="service" required maxlength="120" value={selected.service}/></label><label>Briefing<textarea name="brief" required minlength="10" maxlength="4000" rows="6">{selected.brief}</textarea></label><label>Obra de referência<select name="referenceId" value={selected.referenceId||selected.reference?.id||''}><option value="">Sem referência</option>{#each data.references as reference}<option value={reference.id}>{reference.title}</option>{/each}</select></label>
      <input type="hidden" name="id" value={selected.id}/><div class="drawer-fields"><label>Estado<select name="status" value={selected.status}>{#each Object.entries(statuses) as [value,label]}<option {value}>{label}</option>{/each}</select></label><label>Prioridade<select name="priority" value={selected.priority||'normal'}>{#each Object.entries(priorities) as [value,label]}<option {value}>{label}</option>{/each}</select></label></div>
      <div class="drawer-fields"><label>Orçamento (centavos de R$)<input name="quoteCents" type="number" min="0" max="100000000" step="1" value={selected.quoteCents||0}/><span>Ex.: 15000 = R$ 150,00</span></label><label>Prazo<input name="dueDate" type="date" value={selected.dueDate||''}/></label></div>
      <fieldset class="studio-checklist"><legend>Etapas de produção</legend>{#each [['rough','Rascunho'],['cleanup','Limpeza'],['edit','Edição'],['render','Renderização']] as [key,label]}<label><input type="checkbox" name={key} checked={selected.checklist?.[key as 'rough'|'cleanup'|'edit'|'render']||false}/>{label}</label>{/each}</fieldset>
      <label>Notas de direção / orçamento<textarea name="notes" maxlength="4000" rows="6" placeholder="Materiais, próximos passos, valores e observações internas…">{selected.notes||''}</textarea></label><p class="drawer-hint">Somente a direção tem acesso a estas notas. Até 4.000 caracteres.</p>
      <button class="studio-button lime" disabled={busy}>{busy?'Salvando ficha…':'Salvar notas e estado'}<Icon name="check" size={18}/></button>
    </form>
    <form method="POST" action="?/delete" use:enhance={submit} class="drawer-delete" onsubmit={event=>{if(!confirm('Retirar esta ficha da mesa? Os dados serão preservados por exclusão lógica.'))event.preventDefault();}}><input type="hidden" name="id" value={selected.id}/><button disabled={busy}>Retirar da mesa<Icon name="close" size={15}/></button></form>
</dialog>
{/if}
{#if newOpen}
<dialog class="director-drawer create-drawer" bind:this={createDialog} onclose={()=>{newOpen=false;trigger?.focus();}} aria-labelledby="new-scene-heading">
  <div class="drawer-heading"><p class="studio-kicker">SCENE / NOVO ROTEIRO</p><button class="drawer-close" onclick={closeCreate} aria-label="Fechar nova comissão"><Icon name="close" size={24}/></button></div>
  <h2 id="new-scene-heading">Abrir uma<br/>nova cena.</h2><p class="drawer-hint">Registro manual para ideias recebidas por outros canais. Não envia e-mail ao cliente.</p>
  {#if form?.error}<p class="studio-notice error" role="alert">{form.error}</p>{/if}
  <form method="POST" action="?/create" use:enhance={submit} class="director-form"><input type="hidden" name="requestKey" value={data.requestKey}/><label>Nome do cliente<input name="name" required minlength="2" maxlength="120" autocomplete="off"/></label><label>E-mail<input name="email" type="email" required maxlength="254" autocomplete="off"/></label><label>Tipo de serviço<select name="service" required><option value="" disabled selected>Escolha o serviço</option>{#each serviceOptions as service}<option value={service}>{service}</option>{/each}</select></label><label>Obra de referência (opcional)<select name="referenceId"><option value="">Sem referência</option>{#each data.references as reference}<option value={reference.id}>{reference.title}</option>{/each}</select></label><label>Briefing<textarea name="brief" required minlength="10" maxlength="4000" rows="6"></textarea></label><button class="studio-button lime" disabled={busy}>{busy?'Abrindo cena…':'Adicionar à mesa'}<Icon name="plus" size={18}/></button></form>
</dialog>
{/if}
<style>
